import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 17

    try:
        records = list(csv.reader(
            io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
            delimiter=";",
            quotechar='"',
            doublequote=True,
            strict=False,
        ))
    except csv.Error:
        records = []

    records = [
        [value.lstrip("\ufeff") if index == 0 else value for index, value in enumerate(row)]
        for row in records
        if row and any(value.strip() for value in row)
    ]

    def header_score(row):
        nonempty = [value for value in row if value.strip()]
        if not nonempty:
            return None
        alphabetic = sum(bool(re.search(r"[^\W\d_]", value, re.UNICODE)) for value in nonempty)
        if alphabetic < 3 or alphabetic / len(nonempty) < 0.5:
            return None
        return alphabetic, len(nonempty), -abs(len(row) - expected_width)

    header_index = None
    best_score = None
    for index, row in enumerate(records):
        score = header_score(row)
        if score is not None and (best_score is None or score > best_score):
            header_index = index
            best_score = score

    if header_index is None:
        header_index = next(
            (index for index, row in enumerate(records) if len(row) == expected_width),
            0 if records else None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    def fit_width(row):
        row = list(row)
        if len(row) < expected_width:
            row.extend([""] * (expected_width - len(row)))
        elif len(row) > expected_width:
            overflow = row[expected_width - 1:]
            if all(value == "" for value in overflow[1:]):
                row = row[:expected_width]
            else:
                row = row[:expected_width - 1] + [";".join(overflow)]
        return row

    columns = fit_width(records[header_index])
    columns = [
        value if value else f"Column_{index + 1}"
        for index, value in enumerate(columns)
    ]
    rows = [fit_width(row) for row in records[header_index + 1:]]

    return {"columns": columns, "rows": rows}
